eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   servicesData: () => (/* binding */ servicesData)\n/* harmony export */ });\nconst servicesData = [\n    // --- MAGENTO ---\n    {\n        slug: \"magento-development\",\n        category: \"Magento\",\n        title: \"Magento development\",\n        subtitle: \"Custom modules and extensions\",\n        icon: \"fa-code\",\n        intro: \"We extend Magento 2 with modules written for your business: new features, checkout changes and admin tools that leave the core untouched, so upgrades stay simple.\",\n        signs: [\n            {\n                title: \"Your team works around the store\",\n                desc: \"Staff export orders to spreadsheets or re-type data because Magento doesn’t follow your process.\"\n            },\n            {\n                title: \"Extensions fight each other\",\n                desc: \"Overlapping modules slow pages down or break after every update.\"\n            },\n            {\n                title: \"Your checkout doesn’t fit your customers\",\n                desc: \"B2B buyers, special delivery rules or complex product options don’t fit the standard flow.\"\n            },\n            {\n                title: \"Upgrades keep getting postponed\",\n                desc: \"Custom code was written into the core or the theme, so every update turns into a project.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Custom modules\",\n                desc: \"New features as standalone modules, from pricing rules to product configurators.\"\n            },\n            {\n                title: \"Extension customisation\",\n                desc: \"Third-party extensions adapted to how you work, and conflicts between them fixed.\"\n            },\n            {\n                title: \"Checkout and cart\",\n                desc: \"Extra steps, delivery options, validation and payment flows.\"\n            },\n            {\n                title: \"Multi-store setups\",\n                desc: \"Store views per country, language and currency, run from one admin.\"\n            },\n            {\n                title: \"Admin tools\",\n                desc: \"Bulk actions, import and export jobs, and the reports your team actually uses.\"\n            },\n            {\n                title: \"Hyv\\xe4 frontends\",\n                desc: \"Lighter, faster storefronts built on Hyv\\xe4, for new stores or as a Luma replacement.\"\n            }\n        ],\n        deepDive: {\n            title: \"How we build modules that survive upgrades\",\n            content: \"Magento is built to be extended. Done properly, new features live in their own modules and hook into the platform through plugins, observers and service contracts, without editing core files or copying large templates. That separation is what keeps a store upgradeable.\"\n        },\n        faqs: [\n            {\n                q: \"Will custom modules break when Magento updates?\",\n                a: \"We write modules to Magento’s coding standards and keep them out of the core, then test them against each new version before you upgrade.\"\n            },\n            {\n                q: \"Who owns the code?\",\n                a: \"Once the work is paid for, you own the full source code of every custom module we build for you.\"\n            }\n        ]\n    },\n    {\n        slug: \"hyva-development\",\n        category: \"Magento\",\n        title: \"Hyv\\xe4 storefronts\",\n        subtitle: \"Fast themes on Hyv\\xe4 or Luma\",\n        icon: \"fa-bolt\",\n        intro: \"Fast, maintainable storefronts on Hyv\\xe4 or Luma, built from your design or ours, with Core Web Vitals in mind from the first template.\",\n        signs: [\n            {\n                title: \"Pages feel slow on phones\",\n                desc: \"Product and category pages take seconds to become usable on mobile data.\"\n            },\n            {\n                title: \"Core Web Vitals stay red\",\n                desc: \"Search Console flags poor loading or responsiveness, however much caching you add.\"\n            },\n            {\n                title: \"Frontend changes take too long\",\n                desc: \"Small design tweaks mean digging through RequireJS, Knockout and layout XML.\"\n            },\n            {\n                title: \"Your theme is a patchwork\",\n                desc: \"Years of overrides make every update risky and every bug hard to trace.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"New Hyv\\xe4 themes\",\n                desc: \"A storefront built on Hyv\\xe4 from the start, styled to your brand.\"\n            },\n            {\n                title: \"Luma to Hyv\\xe4\",\n                desc: \"An existing Luma theme moved to Hyv\\xe4, including your extensions.\"\n            },\n            {\n                title: \"Extension compatibility\",\n                desc: \"Hyv\\xe4 versions of third-party extensions that only ship Luma templates.\"\n            },\n            {\n                title: \"Product and category pages\",\n                desc: \"Clear product pages, filters and listings that are quick to scan.\"\n            },\n            {\n                title: \"Cart and checkout\",\n                desc: \"Shorter steps and clearer forms between the basket and the order.\"\n            },\n            {\n                title: \"UI improvements\",\n                desc: \"Targeted fixes to navigation, search, mini-cart and forms on an existing theme.\"\n            }\n        ],\n        deepDive: {\n            title: \"What changes when you move to Hyv\\xe4\",\n            content: \"Hyv\\xe4 replaces Magento’s default frontend, built on RequireJS, Knockout and jQuery, with Tailwind CSS and Alpine.js. Pages ship far less JavaScript, so they load and respond faster, especially on mobile.\"\n        },\n        faqs: [\n            {\n                q: \"Is Hyv\\xe4 right for my store?\",\n                a: \"If speed and frontend upkeep matter to you, often yes. We check your extensions first, because each one needs a Hyv\\xe4-compatible version.\"\n            },\n            {\n                q: \"Can you work from our designer’s files?\",\n                a: \"Yes. We build from your designs, or our designers create them first.\"\n            }\n        ]\n    },\n    {\n        slug: \"magento-maintenance\",\n        category: \"Magento\",\n        title: \"Upgrades and maintenance\",\n        subtitle: \"Patches, upgrades and fixes\",\n        icon: \"fa-shield-alt\",\n        intro: \"Version upgrades, security patches, extension compatibility and bug fixing, on a schedule or whenever you need it.\",\n        signs: [\n            {\n                title: \"You’re more than one release behind\",\n                desc: \"Older versions stop receiving security patches, and the jump gets bigger every month you wait.\"\n            },\n            {\n                title: \"Updates feel risky\",\n                desc: \"Nobody wants to touch the store because the last update broke something.\"\n            },\n            {\n                title: \"Small issues pile up\",\n                desc: \"Bugs and change requests sit in a list with no one responsible for clearing it.\"\n            },\n            {\n                title: \"Customers find problems first\",\n                desc: \"A broken checkout or a failed cron job goes unnoticed until someone complains.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Version upgrades\",\n                desc: \"Your store moved to the current Magento 2.4 release, tested on staging first.\"\n            },\n            {\n                title: \"Security patches\",\n                desc: \"Adobe security patches applied as they are released.\"\n            },\n            {\n                title: \"Extension updates\",\n                desc: \"Third-party extensions updated and tested so they keep working together.\"\n            },\n            {\n                title: \"Compatibility\",\n                desc: \"PHP, OpenSearch and other services kept on versions Magento supports.\"\n            },\n            {\n                title: \"Bug fixing\",\n                desc: \"Errors in checkout, indexing, cron jobs and the admin found and fixed.\"\n            },\n            {\n                title: \"Safe deployments\",\n                desc: \"Changes released with a way back if anything goes wrong.\"\n            }\n        ],\n        deepDive: {\n            title: \"What a Magento upgrade really involves\",\n            content: \"An upgrade is more than running Composer. Each Magento release can change the PHP and OpenSearch versions it needs, retire code that extensions rely on, and alter database structures.\"\n        },\n        faqs: [\n            {\n                q: \"How often should a Magento store be updated?\",\n                a: \"Apply security patches soon after Adobe releases them, and plan a version upgrade at least once a year.\"\n            },\n            {\n                q: \"Can you upgrade a store that’s several versions behind?\",\n                a: \"Yes. We plan the upgrade in steps and test each one on a staging copy of your store.\"\n            }\n        ]\n    },\n    {\n        slug: \"magento-integrations\",\n        category: \"Magento\",\n        title: \"Integrations and automation\",\n        subtitle: \"ERP, WMS, CRM and APIs\",\n        icon: \"fa-network-wired\",\n        intro: \"Magento connected to your ERP, WMS, CRM, payment and shipping providers, with stock, orders and prices kept in sync automatically.\",\n        signs: [\n            {\n                title: \"Orders are re-typed\",\n                desc: \"Someone copies orders from Magento into your ERP or warehouse system.\"\n            },\n            {\n                title: \"Stock is out of date\",\n                desc: \"You sell items that are out of stock, or hide items that are actually available.\"\n            },\n            {\n                title: \"Prices don’t match\",\n                desc: \"Price lists live in the ERP while the store shows something else.\"\n            },\n            {\n                title: \"Customer service can’t see orders\",\n                desc: \"Support agents switch between tools to find an order’s status.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"ERP and WMS\",\n                desc: \"Products, stock and orders flowing between Magento, your ERP and your warehouse.\"\n            },\n            {\n                title: \"CRM and help desk\",\n                desc: \"Customer and order data in your CRM, and order details inside Zendesk.\"\n            },\n            {\n                title: \"Payments and shipping\",\n                desc: \"Payment gateways and shipping carriers connected to checkout and fulfilment.\"\n            },\n            {\n                title: \"Custom APIs\",\n                desc: \"REST and GraphQL endpoints for apps, partners and marketplaces.\"\n            },\n            {\n                title: \"Scheduled jobs\",\n                desc: \"Imports, exports and price updates that run on their own and alert you when they fail.\"\n            },\n            {\n                title: \"AI-assisted workflows\",\n                desc: \"Automations such as AI-assisted product translations for multi-language stores.\"\n            }\n        ],\n        deepDive: {\n            title: \"What makes an integration reliable\",\n            content: \"Most integrations work on day one. The difference shows months later, when an API changes, a job times out or a product arrives with missing data. A reliable integration expects those failures.\"\n        },\n        faqs: [\n            {\n                q: \"Can you connect our ERP?\",\n                a: \"Most likely. If it has an API or a file export, we can connect it. Tell us which system you use.\"\n            },\n            {\n                q: \"What happens when a sync fails?\",\n                a: \"We log failed jobs, retry them and alert you, so orders and stock don’t drift out of sync unnoticed.\"\n            }\n        ]\n    },\n    {\n        slug: \"magento-performance\",\n        category: \"Magento\",\n        title: \"Performance and technical SEO\",\n        subtitle: \"Speed, caching and indexing\",\n        icon: \"fa-tachometer-alt\",\n        intro: \"Faster pages and a cleaner index: Varnish and Redis tuning, database optimisation, Core Web Vitals, structured data and indexing fixes.\",\n        signs: [\n            {\n                title: \"Category pages take seconds\",\n                desc: \"Especially with filters applied or on large catalogues.\"\n            },\n            {\n                title: \"The admin is slow too\",\n                desc: \"Saving products, reindexing or opening the order grid takes far too long.\"\n            },\n            {\n                title: \"Traffic peaks bring errors\",\n                desc: \"Campaigns and sales cause timeouts and 503 errors instead of orders.\"\n            },\n            {\n                title: \"Core Web Vitals are poor\",\n                desc: \"Search Console marks your key page types as poor or in need of improvement.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Caching\",\n                desc: \"Varnish full-page cache and Redis set up and tuned for your catalogue.\"\n            },\n            {\n                title: \"Database\",\n                desc: \"Slow queries, oversized tables and stuck indexers found and fixed.\"\n            },\n            {\n                title: \"Core Web Vitals\",\n                desc: \"Images, scripts and fonts trimmed so pages load and respond faster.\"\n            },\n            {\n                title: \"On-site search\",\n                desc: \"OpenSearch tuned so search results stay fast and relevant.\"\n            },\n            {\n                title: \"Technical SEO\",\n                desc: \"Clean URLs, canonical tags, sitemaps and structured data.\"\n            },\n            {\n                title: \"Multi-store SEO\",\n                desc: \"Correct hreflang tags so Google shows the right store in each country.\"\n            }\n        ],\n        deepDive: {\n            title: \"Where Magento speed is usually lost\",\n            content: \"Magento slowness usually comes from a handful of causes: a full-page cache that isn’t hitting, heavy frontend JavaScript, slow or oversized database tables, and third-party scripts that block the page from rendering.\"\n        },\n        faqs: [\n            {\n                q: \"How do you measure speed?\",\n                a: \"With real-visitor data from Google’s Core Web Vitals report, plus lab tests on your home, category, product and checkout pages.\"\n            },\n            {\n                q: \"Will a faster store rank higher?\",\n                a: \"Page experience is one of many signals Google uses, so speed helps but isn’t a guarantee.\"\n            }\n        ]\n    },\n    // --- SERVERS AND SECURITY ---\n    {\n        slug: \"server-management\",\n        category: \"Servers and security\",\n        title: \"Server management\",\n        subtitle: \"Linux, PHP-FPM, MySQL, Redis\",\n        icon: \"fa-server\",\n        intro: \"Linux administration for Magento hosting: PHP-FPM, MySQL and MariaDB, Redis, Varnish and cron, with monitoring that catches load before it becomes an outage.\",\n        signs: [\n            {\n                title: \"Load spikes take the store down\",\n                desc: \"CPU or memory runs out during sales, imports or bot traffic.\"\n            },\n            {\n                title: \"Cron jobs fail silently\",\n                desc: \"Indexers, emails and imports stop running and nobody notices for days.\"\n            },\n            {\n                title: \"Nobody tunes the server\",\n                desc: \"The host keeps it online, but no one configures it for Magento.\"\n            },\n            {\n                title: \"Disks fill up\",\n                desc: \"Logs, sessions and old backups grow until the store stops working.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Server setup\",\n                desc: \"New servers configured for Magento from the start.\"\n            },\n            {\n                title: \"Resource monitoring\",\n                desc: \"CPU, memory and disk tracked, with alerts before limits are reached.\"\n            },\n            {\n                title: \"PHP-FPM tuning\",\n                desc: \"Worker pools sized to your traffic, so requests don’t queue at busy times.\"\n            },\n            {\n                title: \"Database administration\",\n                desc: \"MySQL and MariaDB configured, tuned and kept healthy.\"\n            },\n            {\n                title: \"Cron jobs\",\n                desc: \"Scheduled tasks that run on time and don’t pile up.\"\n            },\n            {\n                title: \"Troubleshooting\",\n                desc: \"The cause of slowdowns, crashes and overloads found and fixed.\"\n            }\n        ],\n        deepDive: {\n            title: \"What a well-run Magento server looks like\",\n            content: \"Magento relies on several services that all need care: PHP-FPM, a MySQL or MariaDB database, Redis for cache and sessions, Varnish for full-page cache, OpenSearch for search, and cron for background work.\"\n        },\n        faqs: [\n            {\n                q: \"Do you work with our current hosting?\",\n                a: \"Yes, as long as we have server access. If your current setup holds the store back, we can help you move.\"\n            },\n            {\n                q: \"When are you available if something breaks?\",\n                a: \"Stores on monthly plans are monitored around the clock, and critical issues at weekends and holidays are covered too.\"\n            }\n        ]\n    },\n    {\n        slug: \"server-security\",\n        category: \"Servers and security\",\n        title: \"Security and hardening\",\n        subtitle: \"Cloudflare, firewalls and access\",\n        icon: \"fa-shield-alt\",\n        intro: \"Cloudflare WAF and rate limits, firewall rules, IP restrictions, admin access control and security updates that keep bots and attackers away from your checkout.\",\n        signs: [\n            {\n                title: \"Security patches are missing\",\n                desc: \"Known vulnerabilities stay open long after Adobe has released the fix.\"\n            },\n            {\n                title: \"The admin is wide open\",\n                desc: \"It sits on the default path, without two-factor login or IP limits.\"\n            },\n            {\n                title: \"Bots eat your resources\",\n                desc: \"Scrapers and login-guessing bots slow the store down for real shoppers.\"\n            },\n            {\n                title: \"Too many people have access\",\n                desc: \"Former staff and old agencies still have admin or server accounts.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Cloudflare WAF\",\n                desc: \"Firewall rules and managed rulesets in front of your store.\"\n            },\n            {\n                title: \"Rate limiting\",\n                desc: \"Limits that stop bots and brute-force attempts without blocking shoppers.\"\n            },\n            {\n                title: \"Firewall and IP rules\",\n                desc: \"Server firewalls and IP allow-lists for the admin, SSH and databases.\"\n            },\n            {\n                title: \"Admin protection\",\n                desc: \"Two-factor login, a private admin URL and the right role for each user.\"\n            },\n            {\n                title: \"Security updates\",\n                desc: \"Operating system, PHP and Magento security patches applied promptly.\"\n            },\n            {\n                title: \"Vulnerability fixes\",\n                desc: \"Known weaknesses found and fixed before anyone can use them.\"\n            }\n        ],\n        deepDive: {\n            title: \"How Magento stores usually get attacked\",\n            content: \"Most attacks aren’t personal. Automated tools scan the internet for stores with known vulnerabilities, weak admin logins or outdated extensions, and exploit them at scale. Defence comes in layers.\"\n        },\n        faqs: [\n            {\n                q: \"Will Cloudflare block Google or my customers?\",\n                a: \"Not when it’s set up properly. We exempt verified search engine bots and tune the rules so real shoppers get through.\"\n            },\n            {\n                q: \"Is Cloudflare enough on its own?\",\n                a: \"No. It blocks a lot of automated traffic, but patching, access control and server hardening are still needed behind it.\"\n            }\n        ]\n    },\n    // --- BEYOND MAGENTO ---\n    {\n        slug: \"web-development\",\n        category: \"Beyond Magento\",\n        title: \"Custom web development\",\n        subtitle: \"PHP apps, APIs and websites\",\n        icon: \"fa-laptop-code\",\n        intro: \"PHP and JavaScript applications, APIs, databases and business websites, built around how your business actually works.\",\n        signs: [\n            {\n                title: \"Your process doesn’t fit the tool\",\n                desc: \"Your team bends its way of working to match software built for someone else.\"\n            },\n            {\n                title: \"Data lives in spreadsheets\",\n                desc: \"Important information is spread across files only one person understands.\"\n            },\n            {\n                title: \"Plugins keep piling up\",\n                desc: \"A site held together by many plugins is slow and hard to update.\"\n            },\n            {\n                title: \"Systems don’t talk to each other\",\n                desc: \"The same data is entered in several places by hand.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Business websites\",\n                desc: \"Fast websites for companies and brands that your team can update.\"\n            },\n            {\n                title: \"Web applications\",\n                desc: \"Portals, booking systems and internal tools built around your process.\"\n            },\n            {\n                title: \"APIs\",\n                desc: \"REST APIs that connect your systems, apps and partners.\"\n            },\n            {\n                title: \"Databases\",\n                desc: \"Database design, migrations and reporting.\"\n            },\n            {\n                title: \"Admin areas\",\n                desc: \"Simple admin panels so your team can manage content and data.\"\n            },\n            {\n                title: \"Ongoing support\",\n                desc: \"Updates, fixes and improvements to sites we or others built.\"\n            }\n        ],\n        deepDive: {\n            title: \"Custom build or off-the-shelf?\",\n            content: \"Custom software isn’t always the answer. If a reliable product already does what you need, using it is usually faster and cheaper. A custom build makes sense when your process is what sets you apart.\"\n        },\n        faqs: [\n            {\n                q: \"Do you build on a CMS or from scratch?\",\n                a: \"Whichever fits. A CMS suits content-heavy sites; custom PHP suits tools and portals with their own logic.\"\n            },\n            {\n                q: \"Can you work on our existing website?\",\n                a: \"Yes. We review the code first, then fix, extend or rebuild where it makes sense.\"\n            }\n        ]\n    },\n    {\n        slug: \"web-design\",\n        category: \"Beyond Magento\",\n        title: \"Web design and UI/UX\",\n        subtitle: \"Interfaces and landing pages\",\n        icon: \"fa-pencil-ruler\",\n        intro: \"Responsive interfaces, landing pages and visual design that balances usability with your brand.\",\n        signs: [\n            {\n                title: \"Visitors leave quickly\",\n                desc: \"People land on key pages and leave without finding what they came for.\"\n            },\n            {\n                title: \"It doesn’t work well on phones\",\n                desc: \"Text is small, buttons are cramped and forms are hard to fill in.\"\n            },\n            {\n                title: \"It no longer looks like you\",\n                desc: \"Your products, prices or positioning have moved on and the site hasn’t.\"\n            },\n            {\n                title: \"Every change needs a developer\",\n                desc: \"Simple updates to pages or banners turn into small projects.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Websites\",\n                desc: \"Page layouts for desktop and mobile, from the home page to contact forms.\"\n            },\n            {\n                title: \"eCommerce UX\",\n                desc: \"Product pages, filters, cart and checkout that are easy to use.\"\n            },\n            {\n                title: \"Landing pages\",\n                desc: \"Focused pages for campaigns and product launches.\"\n            },\n            {\n                title: \"Design systems\",\n                desc: \"Colours, type and components your developers can reuse.\"\n            },\n            {\n                title: \"Prototypes\",\n                desc: \"Clickable prototypes to test ideas before anything is built.\"\n            },\n            {\n                title: \"Redesigns\",\n                desc: \"An existing site improved without starting from scratch.\"\n            }\n        ],\n        deepDive: {\n            title: \"How we approach a redesign\",\n            content: \"A good redesign starts with what isn’t working, not with colours. We look at your analytics, your most visited pages and the questions customers ask, so the new design solves real problems.\"\n        },\n        faqs: [\n            {\n                q: \"Do you also build what you design?\",\n                a: \"Yes. The same team designs and develops, so nothing gets lost between the two.\"\n            },\n            {\n                q: \"Can you work with our brand guidelines?\",\n                a: \"Yes. We design within your existing brand, or help you define one.\"\n            }\n        ]\n    },\n    {\n        slug: \"digital-marketing\",\n        category: \"Beyond Magento\",\n        title: \"Digital marketing\",\n        subtitle: \"Google Ads, Meta Ads and SEO\",\n        icon: \"fa-bullhorn\",\n        intro: \"Google Ads, Facebook Ads and SEO campaigns that bring the right visitors to your store.\",\n        signs: [\n            {\n                title: \"Ad spend rises, sales don’t\",\n                desc: \"Campaigns cost more each month without a matching rise in orders.\"\n            },\n            {\n                title: \"You can’t tell what works\",\n                desc: \"Conversions aren’t tracked properly, so every decision is a guess.\"\n            },\n            {\n                title: \"Organic traffic has stalled\",\n                desc: \"Rankings slipped after a redesign, or have been flat for a year.\"\n            },\n            {\n                title: \"Product feeds get rejected\",\n                desc: \"Google Merchant Center or Meta flags errors and products stop showing in ads.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Google Ads\",\n                desc: \"Search and Shopping campaigns focused on your best-selling products.\"\n            },\n            {\n                title: \"Facebook and Instagram ads\",\n                desc: \"Campaigns that reach new customers and bring back past visitors.\"\n            },\n            {\n                title: \"SEO\",\n                desc: \"Keyword research and on-page improvements that grow organic traffic.\"\n            },\n            {\n                title: \"Content writing\",\n                desc: \"Product descriptions and articles written for your customers and for search.\"\n            },\n            {\n                title: \"Tracking\",\n                desc: \"Google Analytics 4, conversion tracking and product feeds set up correctly.\"\n            },\n            {\n                title: \"Reporting\",\n                desc: \"Clear reports on spend, sales and what to change next.\"\n            }\n        ],\n        deepDive: {\n            title: \"Why marketing and development work better together\",\n            content: \"Many marketing problems are technical underneath: broken conversion tracking, slow landing pages, product feeds with missing data, or pages Google can’t index properly. We fix the cause, then run campaigns.\"\n        },\n        faqs: [\n            {\n                q: \"How soon will I see results?\",\n                a: \"Paid ads can bring traffic within days. SEO takes longer, often months, because search engines need time to re-crawl and re-evaluate your pages.\"\n            },\n            {\n                q: \"Do you run ads in our own accounts?\",\n                a: \"Yes. Campaigns run in your own Google and Meta accounts, so you keep full access and all the history.\"\n            }\n        ]\n    },\n    {\n        slug: \"graphic-design\",\n        category: \"Beyond Magento\",\n        title: \"Graphic design\",\n        subtitle: \"Logos, print and brand\",\n        icon: \"fa-palette\",\n        intro: \"Logos, brand identity, print design and visual assets that make your business look professional across every channel.\",\n        signs: [\n            {\n                title: \"Inconsistent branding\",\n                desc: \"Different logos, colours and fonts used across your website, social media and print.\"\n            },\n            {\n                title: \"DIY design looks DIY\",\n                desc: \"Important business documents and ads look unpolished compared to competitors.\"\n            },\n            {\n                title: \"Print files get rejected\",\n                desc: \"Printers reject files because they aren’t set up correctly for bleed, colour or resolution.\"\n            },\n            {\n                title: \"No brand guidelines\",\n                desc: \"You can’t hand a designer your assets and expect them to match your existing style.\"\n            }\n        ],\n        whatWeBuild: [\n            {\n                title: \"Logo design\",\n                desc: \"Unique logos designed to work in both print and digital formats.\"\n            },\n            {\n                title: \"Brand identity\",\n                desc: \"Typography, colour palettes, and usage guidelines.\"\n            },\n            {\n                title: \"Print design\",\n                desc: \"Business cards, brochures, flyers, and packaging.\"\n            },\n            {\n                title: \"Social media assets\",\n                desc: \"Templates and graphics for consistent social media presence.\"\n            },\n            {\n                title: \"Marketing materials\",\n                desc: \"Banners, pitch decks, and advertising graphics.\"\n            },\n            {\n                title: \"Brand guidelines\",\n                desc: \"A rulebook for how your brand looks and sounds everywhere.\"\n            }\n        ],\n        deepDive: {\n            title: \"Why brand consistency matters\",\n            content: \"Your brand is more than just a logo. It is the visual and emotional identity that helps customers recognize and trust your business. Consistent graphic design across all touchpoints builds professionalism and credibility.\"\n        },\n        faqs: [\n            {\n                q: \"What file formats do I get?\",\n                a: \"You receive vector source files (AI, EPS, SVG) for scalable printing, plus high-resolution PNG and JPG files for digital use.\"\n            },\n            {\n                q: \"Do I own the rights to the designs?\",\n                a: \"Yes, upon final payment, you receive full ownership and copyright of all custom designs created for your brand.\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/services-data.ts\n");

